// Parsear mensaje WhatsApp de Meta Cloud API
const body = $input.first().json.body || $input.first().json;

// 1. Verificación de Webhook (Meta Hub Challenge)
if (body["hub.mode"] === "subscribe") {
  return [{ json: { isVerification: true, challenge: body["hub.challenge"] } }];
}

const entry = body.entry?.[0];
const change = entry?.changes?.[0]?.value;
const message = change?.messages?.[0];
const contact = change?.contacts?.[0];

if (!message) {
  return [];
}

const senderPhone = message.from;
const senderName = contact?.profile?.name || "Paciente";
const messageType = message.type;
let userText = "";
let mediaId = null;
let mimeType = null;

if (messageType === "text") {
  userText = message.text?.body || "";
} else if (messageType === "image") {
  userText = message.image?.caption || "[Foto de récipe/orden médica]";
  mediaId = message.image?.id;
  mimeType = message.image?.mime_type;
} else if (messageType === "audio" || messageType === "voice") {
  mediaId = message.audio?.id || message.voice?.id;
  mimeType = message.audio?.mime_type || message.voice?.mime_type;
  userText = "[Nota de voz del paciente]";
}

return [{
  json: {
    isVerification: false,
    senderPhone,
    senderName,
    messageType,
    userText,
    mediaId,
    mimeType,
    messageId: message.id,
    timestamp: message.timestamp
  }
}];

return JSON.stringify({
  status: 'success',
  info: 'Catálogo oficial cargado con 80+ exámenes y condiciones preanalíticas del laboratorio.'
});
